def analyze(inp, out):
    h, w = len(inp), len(inp[0])
    dmap = {}
    for i in range(h):
        for j in range(w):
            if inp[i][j]:
                dmap.setdefault(i-j, set()).add(inp[i][j])
    print('d-map:', {k: sorted(v) for k, v in sorted(dmap.items())})
    # check output is function of (i-j) mod p, find smallest p
    for p in range(1, 20):
        m = {}
        ok = True
        for i in range(h):
            for j in range(w):
                r = (i-j) % p
                if r in m and m[r] != out[i][j]: ok = False; break
                m[r] = out[i][j]
            if not ok: break
        if ok: print('period', p, m); break

