fn = '''
def diag_period_colors(grid):
    """Map each residue r of i-j (mod the smallest consistent period) to the color of the nonzero cells on those diagonals."""
    h, w = len(grid), len(grid[0])
    dmap = {}
    for i in range(h):
        for j in range(w):
            if grid[i][j]:
                d = i - j
                if d in dmap and dmap[d] != grid[i][j]:
                    return None
                dmap[d] = grid[i][j]
    for p in range(1, max(h, w) + 1):
        m = {}
        ok = True
        for d, c in dmap.items():
            r = d % p
            if r in m and m[r] != c:
                ok = False
                break
            m[r] = c
        if ok:
            return p, m
    return None

def fill_diagonal_pattern(grid):
    """Fill every cell by its diagonal residue: color of (i-j) mod p, with p and the mapping learned from the nonzero cells."""
    res = diag_period_colors(grid)
    p, m = res
    h, w = len(grid), len(grid[0])
    return [[m[(i - j) % p] for j in range(w)] for i in range(h)]
'''
